  // Number colours light to dark; drop any that ended up unused.
  const used = [...new Set(label)];
  const order = used.sort((a, b) => { const L = (q) => 0.299 * q[0] + 0.587 * q[1] + 0.114 * q[2]; return L(centres[b]) - L(centres[a]); });
