  for (const p of words) for (let i = 0; i < p.word.length; i++) solution[(p.y + (p.dir === "down" ? i : 0)) * w + p.x + (p.dir === "across" ? i : 0)] = p.word[i];
  return { w, h, words, solution, entries: Array(w * h).fill(""), shown: [], seconds: 0 };
